collectLinkRoute = function() {
  var origin, path;
  log("collectLinkRoute");
  firstLoad = false;
  path = location.pathname.slice(1);
  if (path) {
    globalThis.specialLinkName = path.toLowerCase();
    origin = location.origin;
    history.replaceState(null, "", origin);
  }
};

